    [Parameter] public int RatingCount { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private int HoveredStar { get; set; }
    private int SelectedStar { get; set; }
    private bool RatingSubmitted { get; set; }

    private void SubmitRating(int stars)
    {
        SelectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        RatingSubmitted = true;
    }

    private static string FormatRating(double rating)
    {
        var fullStars = (int)Math.Round(rating);
        return new string('★', fullStars) + new string('☆', 5 - fullStars);
    }
}

