toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted successfully!</h4>
        <p>Your recipe "<strong>@Model.Title</strong>" has been added.</p>
        <a href="@($"recipe/{SubmittedRecipeId}")" class="btn btn-primary">View Recipe</a>
        <a href="submit" class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</a>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="Model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => Model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="Model.Category" class="form-control">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Asian">Asian</option>
                <option value="Desserts">Desserts</option>
                <option value="Salads">Salads</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => Model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" class="form-control" rows="6" placeholder="1 cup flour&#10;2 eggs&#10;..." />
            <ValidationMessage For="() => Model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Model.Steps" class="form-control" rows="6" placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;..." />
            <ValidationMessage For="() => Model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel Model { get; set; } = new();
    private bool Submitted { get; set; }
    private int SubmittedRecipeId { get; set; }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = Model.Title,
            Category = Model.Category,
            Ingredients = Model.Ingredients,
            Steps = Model.Steps
        };
        RecipeService.AddRecipe(recipe);
        SubmittedRecipeId = recipe.Id;
        Submitted = true;
    }

    private void Reset()
    {
        Model = new();
        Submitted = false;
    }
}

using System.ComponentModel.DataAnnotations;

